"""State-vector simulation and deterministic shot sampling."""

from __future__ import annotations

import cmath
import math
import random

from .openqasm import Operation, Program

_SQRT1_2 = 2.0**-0.5


def _hadamard(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = (a + b) * _SQRT1_2
            state[high] = (a - b) * _SQRT1_2


def _pauli_x(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            state[low], state[high] = state[high], state[low]


def _pauli_y(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = -1j * b
            state[high] = 1j * a


# Phase gates diag(1, phase): z, s/sdg (diag(1, +-i)) and t/tdg
# (phase exp(+-i*pi/4)).
_PHASE_GATES = {
    "z": -1 + 0j,
    "s": 1j,
    "sdg": -1j,
    "t": cmath.exp(0.25j * math.pi),
    "tdg": cmath.exp(-0.25j * math.pi),
}


def _phase(state: list[complex], qubit: int, num_qubits: int, factor: complex) -> None:
    bit = 1 << qubit
    for index in range(1 << num_qubits):
        if index & bit:
            state[index] = factor * state[index]


def _swap(state: list[complex], first: int, second: int, num_qubits: int) -> None:
    first_bit = 1 << first
    second_bit = 1 << second
    for index in range(1 << num_qubits):
        if (index & first_bit) and not (index & second_bit):
            other = (index ^ first_bit) | second_bit
            state[index], state[other] = state[other], state[index]


def _controlled_x(state: list[complex], control: int, target: int, num_qubits: int) -> None:
    cbit = 1 << control
    tbit = 1 << target
    for index in range(1 << num_qubits):
        if (index & cbit) and not (index & tbit):
            other = index | tbit
            if index < other:
                state[index], state[other] = state[other], state[index]


def _controlled_single(
    state: list[complex],
    control: int,
    target: int,
    num_qubits: int,
    matrix: tuple[complex, complex, complex, complex],
) -> None:
    """Apply a single-qubit matrix to *target* where the *control* bit is 1."""
    g00, g01, g10, g11 = matrix
    cbit = 1 << control
    tbit = 1 << target
    step = tbit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + tbit):
            if not (low & cbit):
                continue
            high = low | tbit
            a = state[low]
            b = state[high]
            state[low] = g00 * a + g01 * b
            state[high] = g10 * a + g11 * b


def _rotation_matrix(kind: str, theta: float) -> tuple[complex, complex, complex, complex]:
    """The single-qubit matrix of an rx/ry/rz rotation by *theta* radians."""
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    if kind == "rx":
        return (c, -1j * s, -1j * s, c)
    if kind == "ry":
        return (c, -s, s, c)
    # rz
    return (cmath.exp(-0.5j * theta), 0j, 0j, cmath.exp(0.5j * theta))


def _rx(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = c * a - 1j * s * b
            state[high] = -1j * s * a + c * b


def _ry(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = c * a - s * b
            state[high] = s * a + c * b


def _rz(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    lo_factor = cmath.exp(-0.5j * theta)
    hi_factor = cmath.exp(0.5j * theta)
    bit = 1 << qubit
    for index in range(1 << num_qubits):
        if index & bit:
            state[index] = hi_factor * state[index]
        else:
            state[index] = lo_factor * state[index]


def _apply_gate(state: list[complex], op: Operation, num_qubits: int) -> None:
    """Apply one (non-measurement) *op* to *state* in place."""
    if op.kind == "x":
        _pauli_x(state, op.targets[0], num_qubits)
    elif op.kind == "h":
        _hadamard(state, op.targets[0], num_qubits)
    elif op.kind == "y":
        _pauli_y(state, op.targets[0], num_qubits)
    elif op.kind in _PHASE_GATES:
        _phase(state, op.targets[0], num_qubits, _PHASE_GATES[op.kind])
    elif op.kind == "swap":
        _swap(state, op.targets[0], op.targets[1], num_qubits)
    elif op.kind == "cx":
        _controlled_x(state, op.targets[0], op.targets[1], num_qubits)
    elif op.kind == "cz":
        _controlled_single(
            state, op.targets[0], op.targets[1], num_qubits, (1 + 0j, 0j, 0j, -1 + 0j)
        )
    elif op.kind == "rx":
        _rx(state, op.targets[0], num_qubits, op.params[0])
    elif op.kind == "ry":
        _ry(state, op.targets[0], num_qubits, op.params[0])
    elif op.kind == "rz":
        _rz(state, op.targets[0], num_qubits, op.params[0])
    elif op.kind in ("crx", "cry", "crz"):
        matrix = _rotation_matrix(op.kind[1:], op.params[0])
        _controlled_single(state, op.targets[0], op.targets[1], num_qubits, matrix)


def simulate_state_vector(program: Program) -> list[complex]:
    """Return the final state vector after applying all quantum gates.

    Basis-state integer ``k`` stores qubit ``i`` in bit ``i`` (q[0] is the
    least significant bit). Measurements do not collapse the state: the spec
    guarantees every measurement comes after every gate and each qubit is
    measured at most once, so non-destructive sampling of the final state is
    equivalent.
    """
    n = program.num_qubits
    state = [0j] * (1 << n)
    state[0] = 1 + 0j

    for op in program.operations:
        if op.kind == "measure":
            # Measurements affect only the sampled classical outcomes.
            continue
        _apply_gate(state, op, n)
    return state


def unitary_matrix(program: Program) -> list[list[complex]]:
    """Return the full unitary U induced by the gates (pre-measurement).

    The matrix acts on basis vectors with qubit ``i`` in bit ``i`` (q[0] is
    the least significant bit), matching :func:`simulate_state_vector`.
    Measurement operations are ignored. Columns are evolved independently by
    applying each gate in source order, so for a circuit with gates G1..Gk the
    result is U = Gk @ ... @ G1.
    """
    n = program.num_qubits
    dim = 1 << n
    gate_ops = [op for op in program.operations if op.kind != "measure"]

    columns: list[list[complex]] = []
    for start in range(dim):
        state = [0j] * dim
        state[start] = 1 + 0j
        for op in gate_ops:
            _apply_gate(state, op, n)
        columns.append(state)

    # Transpose columns-of-U into rows.
    return [[columns[col][row] for col in range(dim)] for row in range(dim)]


def measurement_probabilities(program: Program, basis_probabilities: list[float]) -> dict[str, float]:
    """Aggregate basis-state probabilities into classical-outcome probabilities.

    Uses the same qubit-to-clbit mapping as :func:`sample_counts` (each
    measured qubit contributes its bit to the classical index; unwritten
    clbits stay 0) and the same fixed-width, lexicographically ordered key
    convention. With no measurements the only possible outcome is the
    all-zero string, carrying total probability 1.
    """
    width = program.num_clbits
    measurements = [(op.targets[0], op.targets[1]) for op in program.operations if op.kind == "measure"]

    if not measurements:
        return {format(0, f"0{width}b") if width else "": 1.0}

    aggregated: dict[int, float] = {}
    for basis, probability in enumerate(basis_probabilities):
        classical = 0
        for qubit, clbit in measurements:
            if (basis >> qubit) & 1:
                classical |= 1 << clbit
        aggregated[classical] = aggregated.get(classical, 0.0) + probability

    return {
        format(classical, f"0{width}b") if width else "": probability
        for classical, probability in sorted(aggregated.items())
    }


def sample_counts(program: Program, state: list[complex], shots: int, seed: int) -> dict[str, int]:
    """Draw *shots* samples from *state* deterministically from *seed*.

    Returns a mapping from fixed-width classical bit strings (highest clbit
    index first) to occurrence counts. Only observed outcomes are present.
    """
    probabilities = [abs(amplitude) ** 2 for amplitude in state]
    return sample_counts_from_probabilities(program, probabilities, shots, seed)


def sample_counts_from_probabilities(
    program: Program, probabilities: list[float], shots: int, seed: int
) -> dict[str, int]:
    """Draw *shots* samples from explicit basis-state probabilities.

    Used by the density-matrix path, which supplies the diagonal of the
    final density matrix; sampling semantics match the state-vector path.
    """
    measurements = [(op.targets[0], op.targets[1]) for op in program.operations if op.kind == "measure"]

    total = sum(probabilities)
    cumulative = []
    running = 0.0
    for probability in probabilities:
        running += probability / total
        cumulative.append(running)
    if cumulative:
        cumulative[-1] = 1.0

    rng = random.Random(seed)
    width = program.num_clbits
    counts: dict[str, int] = {}
    for _ in range(shots):
        point = rng.random()
        # Binary search for the first cumulative value >= point.
        lo, hi = 0, len(cumulative)
        while lo < hi:
            mid = (lo + hi) // 2
            if cumulative[mid] < point:
                lo = mid + 1
            else:
                hi = mid
        basis = lo

        classical = 0
        for qubit, clbit in measurements:
            if (basis >> qubit) & 1:
                classical |= 1 << clbit
        key = format(classical, f"0{width}b") if width else ""
        counts[key] = counts.get(key, 0) + 1

    return dict(sorted(counts.items()))

"""Density-matrix simulation with configurable noise channels.

Enabled via ``simulate --noise-model PATH``. The model is a JSON object with
up to four channel keys (probabilities in ``[0, 1]``):

- ``amplitude_damping``: |1> decays to |0> with probability gamma.
- ``phase_damping``: populations unchanged, off-diagonal entries scaled by
  ``1 - gamma``.
- ``bit_flip``: ``rho -> (1 - p) rho + p X rho X``.
- ``depolarizing``: ``rho -> (1 - p) rho + p I/2`` (the qubit is replaced by
  the maximally mixed state with probability ``p``).

After every quantum gate, each configured channel is applied to every qubit
the gate touched. Qubits of a two-qubit gate (``cx``, ``cz``, ``crx``,
``cry``, ``crz``, ``swap``) are processed in ascending index order; channels
on one qubit are applied in :data:`CHANNEL_ORDER` order.
"""

from __future__ import annotations

import cmath
import json
import math
from collections.abc import Mapping

from .openqasm import Program

# Fixed order in which channels are applied per qubit and echoed back.
CHANNEL_ORDER = ("amplitude_damping", "phase_damping", "bit_flip", "depolarizing")

# A density matrix holds 4**n entries, so noisy simulation is capped well
# below the state-vector register limit.
MAX_NOISE_QUBITS = 10

_SQRT1_2 = 2.0**-0.5


class NoiseModelError(Exception):
    """The noise model content is invalid (reported as ``noise_model_error``)."""


def _reject_constant(value: str) -> None:
    # json accepts NaN/Infinity by default; they are not valid JSON numbers.
    raise NoiseModelError(f"noise model contains non-JSON constant {value!r}")


def _object_pairs(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise NoiseModelError(f"duplicate key {key!r} in noise model")
        result[key] = value
    return result


def parse_noise_model(text: str) -> dict[str, float]:
    """Parse and validate noise-model JSON text.

    Returns the configured channels as a mapping in :data:`CHANNEL_ORDER`
    order with float probabilities, so models differing only in whitespace
    or key order produce identical output. Raises :class:`NoiseModelError`
    on any invalid content.
    """
    try:
        data = json.loads(text, object_pairs_hook=_object_pairs, parse_constant=_reject_constant)
    except json.JSONDecodeError as exc:
        raise NoiseModelError(f"noise model is not valid JSON: {exc}") from None
    if not isinstance(data, dict):
        raise NoiseModelError("noise model must be a JSON object")
    if not data:
        raise NoiseModelError("noise model must configure at least one channel")
    for key, value in data.items():
        if key not in CHANNEL_ORDER:
            raise NoiseModelError(f"unknown noise channel {key!r}")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise NoiseModelError(f"noise channel {key!r} probability must be a JSON number")
        probability = float(value)
        if not math.isfinite(probability):
            raise NoiseModelError(f"noise channel {key!r} probability must be finite")
        if not 0.0 <= probability <= 1.0:
            raise NoiseModelError(f"noise channel {key!r} probability must be between 0 and 1")
    return {channel: float(data[channel]) for channel in CHANNEL_ORDER if channel in data}


def validate_noise_model(model: object) -> dict[str, float]:
    """Validate a noise model given directly as a mapping (the Python DSL).

    Applies the same channel and probability rules as
    :func:`parse_noise_model` and returns the same canonical mapping in
    :data:`CHANNEL_ORDER` order with float probabilities, so a model passed
    as a Python mapping behaves exactly like the equivalent JSON file.
    Raises :class:`NoiseModelError` on any invalid content.
    """
    if isinstance(model, bool) or not isinstance(model, Mapping):
        raise NoiseModelError("noise model must be a mapping of channel names to probabilities")
    if not model:
        raise NoiseModelError("noise model must configure at least one channel")
    for key, value in model.items():
        if not isinstance(key, str) or key not in CHANNEL_ORDER:
            raise NoiseModelError(f"unknown noise channel {key!r}")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise NoiseModelError(f"noise channel {key!r} probability must be a number")
        probability = float(value)
        if not math.isfinite(probability):
            raise NoiseModelError(f"noise channel {key!r} probability must be finite")
        if not 0.0 <= probability <= 1.0:
            raise NoiseModelError(f"noise channel {key!r} probability must be between 0 and 1")
    return {channel: float(model[channel]) for channel in CHANNEL_ORDER if channel in model}


def _basis_offsets(size: int, bit: int):
    """Yield indices below *size* whose ``bit`` is clear, block by block."""
    step = bit << 1
    for base in range(0, size, step):
        yield from range(base, base + bit)


def _gate_matrix(kind: str, params: tuple[float, ...]) -> tuple[complex, complex, complex, complex]:
    if kind == "x":
        return (0j, 1 + 0j, 1 + 0j, 0j)
    if kind == "h":
        return (_SQRT1_2, _SQRT1_2, _SQRT1_2, -_SQRT1_2)
    if kind == "y":
        return (0j, -1j, 1j, 0j)
    if kind == "z":
        return (1 + 0j, 0j, 0j, -1 + 0j)
    if kind == "s":
        return (1 + 0j, 0j, 0j, 1j)
    if kind == "sdg":
        return (1 + 0j, 0j, 0j, -1j)
    if kind == "t":
        return (1 + 0j, 0j, 0j, cmath.exp(0.25j * math.pi))
    if kind == "tdg":
        return (1 + 0j, 0j, 0j, cmath.exp(-0.25j * math.pi))
    theta = params[0]
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    if kind == "rx":
        return (c, -1j * s, -1j * s, c)
    if kind == "ry":
        return (c, -s, s, c)
    if kind == "rz":
        return (cmath.exp(-0.5j * theta), 0j, 0j, cmath.exp(0.5j * theta))
    raise AssertionError(f"no single-qubit matrix for gate {kind!r}")


def _apply_single_qubit(rho: list[list[complex]], qubit: int, size: int, matrix) -> None:
    """Apply ``rho -> U rho U†`` for a single-qubit unitary ``U``."""
    bit = 1 << qubit
    g00, g01, g10, g11 = matrix
    h00, h01 = g00.conjugate(), g01.conjugate()
    h10, h11 = g10.conjugate(), g11.conjugate()
    for i0 in _basis_offsets(size, bit):
        i1 = i0 | bit
        row0 = rho[i0]
        row1 = rho[i1]
        for j0 in _basis_offsets(size, bit):
            j1 = j0 | bit
            m00 = row0[j0]
            m01 = row0[j1]
            m10 = row1[j0]
            m11 = row1[j1]
            t00 = g00 * m00 + g01 * m10
            t01 = g00 * m01 + g01 * m11
            t10 = g10 * m00 + g11 * m10
            t11 = g10 * m01 + g11 * m11
            row0[j0] = t00 * h00 + t01 * h01
            row0[j1] = t00 * h10 + t01 * h11
            row1[j0] = t10 * h00 + t11 * h01
            row1[j1] = t10 * h10 + t11 * h11


def _apply_cx(rho: list[list[complex]], control: int, target: int, size: int) -> None:
    """Apply the cx basis permutation to both axes of the density matrix."""
    cbit = 1 << control
    tbit = 1 << target
    swapped = [i for i in range(size) if (i & cbit) and not (i & tbit)]
    for i in swapped:
        j = i | tbit
        rho[i], rho[j] = rho[j], rho[i]
    for i in swapped:
        j = i | tbit
        for row in rho:
            row[i], row[j] = row[j], row[i]


def _apply_swap(rho: list[list[complex]], first: int, second: int, size: int) -> None:
    """Apply the swap basis permutation to both axes of the density matrix."""
    first_bit = 1 << first
    second_bit = 1 << second
    swapped = [i for i in range(size) if (i & first_bit) and not (i & second_bit)]
    for i in swapped:
        j = (i ^ first_bit) | second_bit
        rho[i], rho[j] = rho[j], rho[i]
    for i in swapped:
        j = (i ^ first_bit) | second_bit
        for row in rho:
            row[i], row[j] = row[j], row[i]


def _apply_controlled(
    rho: list[list[complex]], control: int, target: int, size: int, matrix
) -> None:
    """Apply ``rho -> U rho U†`` for a controlled single-qubit unitary.

    ``U`` acts as the single-qubit *matrix* on *target* when the *control*
    bit is 1 and as the identity otherwise. Done as a left pass (rows whose
    control bit is set) followed by a right pass (columns whose control bit
    is set), which also covers the cross blocks between the two sectors.
    """
    cbit = 1 << control
    tbit = 1 << target
    g00, g01, g10, g11 = matrix
    h00, h01 = g00.conjugate(), g01.conjugate()
    h10, h11 = g10.conjugate(), g11.conjugate()
    for i0 in _basis_offsets(size, tbit):
        if not (i0 & cbit):
            continue
        i1 = i0 | tbit
        row0 = rho[i0]
        row1 = rho[i1]
        for j in range(size):
            m0 = row0[j]
            m1 = row1[j]
            row0[j] = g00 * m0 + g01 * m1
            row1[j] = g10 * m0 + g11 * m1
    for j0 in _basis_offsets(size, tbit):
        if not (j0 & cbit):
            continue
        j1 = j0 | tbit
        for i in range(size):
            row = rho[i]
            m0 = row[j0]
            m1 = row[j1]
            row[j0] = m0 * h00 + m1 * h01
            row[j1] = m0 * h10 + m1 * h11


def _amplitude_damping(rho: list[list[complex]], qubit: int, size: int, gamma: float) -> None:
    bit = 1 << qubit
    scale = math.sqrt(1.0 - gamma)
    damped = 1.0 - gamma
    for i0 in _basis_offsets(size, bit):
        i1 = i0 | bit
        row0 = rho[i0]
        row1 = rho[i1]
        for j0 in _basis_offsets(size, bit):
            j1 = j0 | bit
            m11 = row1[j1]
            row0[j0] = row0[j0] + gamma * m11
            row0[j1] = scale * row0[j1]
            row1[j0] = scale * row1[j0]
            row1[j1] = damped * m11


def _phase_damping(rho: list[list[complex]], qubit: int, size: int, gamma: float) -> None:
    bit = 1 << qubit
    factor = 1.0 - gamma
    for i0 in _basis_offsets(size, bit):
        i1 = i0 | bit
        row0 = rho[i0]
        row1 = rho[i1]
        for j0 in _basis_offsets(size, bit):
            j1 = j0 | bit
            row0[j1] = factor * row0[j1]
            row1[j0] = factor * row1[j0]


def _bit_flip(rho: list[list[complex]], qubit: int, size: int, p: float) -> None:
    bit = 1 << qubit
    keep = 1.0 - p
    for i0 in _basis_offsets(size, bit):
        i1 = i0 | bit
        row0 = rho[i0]
        row1 = rho[i1]
        for j0 in _basis_offsets(size, bit):
            j1 = j0 | bit
            m00 = row0[j0]
            m01 = row0[j1]
            m10 = row1[j0]
            m11 = row1[j1]
            row0[j0] = keep * m00 + p * m11
            row0[j1] = keep * m01 + p * m10
            row1[j0] = keep * m10 + p * m01
            row1[j1] = keep * m11 + p * m00


def _depolarizing(rho: list[list[complex]], qubit: int, size: int, p: float) -> None:
    bit = 1 << qubit
    keep = 1.0 - p
    half = p * 0.5
    for i0 in _basis_offsets(size, bit):
        i1 = i0 | bit
        row0 = rho[i0]
        row1 = rho[i1]
        for j0 in _basis_offsets(size, bit):
            j1 = j0 | bit
            m00 = row0[j0]
            m11 = row1[j1]
            mixed = half * (m00 + m11)
            row0[j0] = keep * m00 + mixed
            row1[j1] = keep * m11 + mixed
            row0[j1] = keep * row0[j1]
            row1[j0] = keep * row1[j0]


_CHANNELS = {
    "amplitude_damping": _amplitude_damping,
    "phase_damping": _phase_damping,
    "bit_flip": _bit_flip,
    "depolarizing": _depolarizing,
}


def evolve_density_matrix(program: Program, noise: dict[str, float]) -> list[list[complex]]:
    """Evolve and return the full final density matrix (row major).

    This is the same gate/noise evolution as :func:`simulate_density_matrix`
    but returns the complete matrix rather than only its diagonal. Noise
    evolution is deterministic and consumes no randomness; measurements do
    not collapse the state, matching the state-vector path.
    """
    n = program.num_qubits
    size = 1 << n
    rho = [[0j] * size for _ in range(size)]
    rho[0][0] = 1 + 0j

    for op in program.operations:
        if op.kind == "measure":
            continue
        if op.kind == "cx":
            _apply_cx(rho, op.targets[0], op.targets[1], size)
        elif op.kind == "swap":
            _apply_swap(rho, op.targets[0], op.targets[1], size)
        elif op.kind == "cz":
            _apply_controlled(
                rho, op.targets[0], op.targets[1], size, (1 + 0j, 0j, 0j, -1 + 0j)
            )
        elif op.kind in ("crx", "cry", "crz"):
            matrix = _gate_matrix(op.kind[1:], op.params)
            _apply_controlled(rho, op.targets[0], op.targets[1], size, matrix)
        else:
            _apply_single_qubit(rho, op.targets[0], size, _gate_matrix(op.kind, op.params))
        for qubit in sorted(set(op.targets)):
            for channel in CHANNEL_ORDER:
                probability = noise.get(channel)
                if probability:
                    _CHANNELS[channel](rho, qubit, size, probability)

    return rho


def simulate_density_matrix(program: Program, noise: dict[str, float]) -> list[float]:
    """Evolve the density matrix under all gates and noise channels.

    Returns the diagonal of the final density matrix (measurement
    probabilities per basis state). Measurements do not collapse the state,
    matching the state-vector path. Noise evolution is deterministic and
    consumes no randomness.
    """
    rho = evolve_density_matrix(program, noise)
    return [row[i].real for i, row in enumerate(rho)]

input.content:
"""Pauli-product observable expectation values.

Used by the ``expectation`` subcommand, which evaluates a list of Pauli
products against the final pre-measurement state. Each observable is a
tensor product of single-qubit Pauli operators; qubits not listed are
acted on by the identity, and an empty operator list is the global
identity. Expectations follow ``Tr(rho P)`` (the state-vector path uses
``<psi|P|psi>``), so they live in ``[-1, 1]``.

The observables document is UTF-8 JSON with the same deterministic,
strict structural style as the other JSON inputs: duplicate keys,
unknown keys, type substitutions (including booleans posing as
integers) and out-of-range counts are all rejected.
"""

from __future__ import annotations

import json
import math

OBSERVABLES_SCHEMA_VERSION = 1
MAX_OBSERVABLES = 100

# Expectations this close to an endpoint are reported as the endpoint.
EXPECTATION_TOLERANCE = 1e-15

_OBSERVABLES_ROOT_KEYS = ("schema_version", "observables")
_OBSERVABLE_KEYS = ("id", "operators")
_OPERATOR_KEYS = ("qubit", "pauli")
_PAULIS = ("X", "Y", "Z")


class ObservableError(Exception):
    """The observables document is invalid (``observable_error``)."""


def _is_json_int(value: object) -> bool:
    # bool is a subclass of int but is not a JSON integer here.
    return isinstance(value, int) and not isinstance(value, bool)


def _reject_constant(value: str) -> None:
    # json accepts NaN/Infinity by default; they are not valid JSON numbers.
    raise ObservableError(f"observables document contains non-JSON constant {value!r}")


def _object_pairs(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ObservableError(f"duplicate key {key!r} in observables document")
        result[key] = value
    return result


def parse_observables(
    text: str, num_qubits: int
) -> list[tuple[str, list[tuple[int, str]]]]:
    """Parse and validate an observables JSON document.

    Returns the observables in input order as ``(id, operators)`` pairs,
    where each operator is a ``(qubit, pauli)`` tuple. *num_qubits* is the
    parsed circuit's register size and bounds every operator qubit. Raises
    :class:`ObservableError` on any syntax, structural, type or range
    problem.
    """
    try:
        data = json.loads(
            text, object_pairs_hook=_object_pairs, parse_constant=_reject_constant
        )
    except json.JSONDecodeError as exc:
        raise ObservableError(f"observables document is not valid JSON: {exc}") from None

    if not isinstance(data, dict):
        raise ObservableError("observables document must be a JSON object")
    for key in data:
        if key not in _OBSERVABLES_ROOT_KEYS:
            raise ObservableError(f"unknown observables document key {key!r}")

    if "schema_version" not in data:
        raise ObservableError("observables document is missing required key 'schema_version'")
    schema_version = data["schema_version"]
    if not _is_json_int(schema_version) or schema_version != OBSERVABLES_SCHEMA_VERSION:
        raise ObservableError(
            f"observables schema_version must be {OBSERVABLES_SCHEMA_VERSION}, "
            f"got {schema_version!r}"
        )

    if "observables" not in data:
        raise ObservableError("observables document is missing required key 'observables'")
    observables = data["observables"]
    if not isinstance(observables, list):
        raise ObservableError("'observables' must be an array")
    if not 1 <= len(observables) <= MAX_OBSERVABLES:
        raise ObservableError(
            f"'observables' must contain between 1 and {MAX_OBSERVABLES} entries, "
            f"got {len(observables)}"
        )

    parsed: list[tuple[str, list[tuple[int, str]]]] = []
    seen_ids: set[str] = set()
    for index, item in enumerate(observables):
        where = f"observables[{index}]"
        if not isinstance(item, dict):
            raise ObservableError(f"{where} must be a JSON object")
        for key in item:
            if key not in _OBSERVABLE_KEYS:
                raise ObservableError(f"{where} has unknown key {key!r}")

        if "id" not in item:
            raise ObservableError(f"{where} is missing required key 'id'")
        observable_id = item["id"]
        if not isinstance(observable_id, str) or not observable_id:
            raise ObservableError(f"{where} 'id' must be a non-empty string")
        if observable_id in seen_ids:
            raise ObservableError(f"duplicate observable id {observable_id!r}")
        seen_ids.add(observable_id)

        if "operators" not in item:
            raise ObservableError(f"{where} is missing required key 'operators'")
        operators = item["operators"]
        if not isinstance(operators, list):
            raise ObservableError(f"{where} 'operators' must be an array")

        parsed_operators: list[tuple[int, str]] = []
        seen_qubits: set[int] = set()
        for op_index, operator in enumerate(operators):
            op_where = f"{where}.operators[{op_index}]"
            if not isinstance(operator, dict):
                raise ObservableError(f"{op_where} must be a JSON object")
            for key in operator:
                if key not in _OPERATOR_KEYS:
                    raise ObservableError(f"{op_where} has unknown key {key!r}")

            if "qubit" not in operator:
                raise ObservableError(f"{op_where} is missing required key 'qubit'")
            qubit = operator["qubit"]
            if not _is_json_int(qubit) or not 0 <= qubit < num_qubits:
                raise ObservableError(
                    f"{op_where} 'qubit' must be an integer between 0 and {num_qubits - 1}, "
                    f"got {qubit!r}"
                )
            if qubit in seen_qubits:
                raise ObservableError(f"{op_where} repeats qubit {qubit} within {where}")
            seen_qubits.add(qubit)

            if "pauli" not in operator:
                raise ObservableError(f"{op_where} is missing required key 'pauli'")
            pauli = operator["pauli"]
            if pauli not in _PAULIS:
                raise ObservableError(
                    f"{op_where} 'pauli' must be one of 'X', 'Y', 'Z', got {pauli!r}"
                )

            parsed_operators.append((qubit, pauli))
        parsed.append((observable_id, parsed_operators))

    return parsed


def snap_expectation(value: float) -> float | int:
    """Snap one expectation for deterministic, in-range output.

    Values no more than :data:`EXPECTATION_TOLERANCE` from zero become
    ``0.0``; values within that distance of -1 or 1 become the integers
    ``-1``/``1``. Other values are clamped to ``[-1, 1]`` so finite
    precision round-off can never report an out-of-range expectation.
    """
    value = min(1.0, max(-1.0, float(value)))
    if abs(value) <= EXPECTATION_TOLERANCE:
        return 0.0
    if abs(value - 1.0) <= EXPECTATION_TOLERANCE:
        return 1
    if abs(value + 1.0) <= EXPECTATION_TOLERANCE:
        return -1
    return value


def _phase_bits(operators: list[tuple[int, str]]) -> tuple[int, int, int]:
    """Decompose a Pauli product into (X-bits, Y-bits, Z-bits) masks."""
    x_bits = 0
    y_bits = 0
    z_bits = 0
    for qubit, pauli in operators:
        bit = 1 << qubit
        if pauli == "X":
            x_bits |= bit
        elif pauli == "Y":
            y_bits |= bit
        else:
            z_bits |= bit
    return x_bits, y_bits, z_bits


def _pauli_phase(
    index: int, z_parity: int, y_count: int, y_parity: int
) -> complex:
    """Scalar phase of ``P|index>``: ``(-1)**z * (-i)**y``."""
    sign = -1.0 if z_parity & 1 else 1.0
    if y_count == 0:
        return sign + 0j
    # y_parity is the parity of Y-site bits set in *index*.
    factor = (1.0, -1j, -1.0, 1j)[y_parity & 3]
    return sign * factor


def state_vector_expectation(
    state: list[complex], operators: list[tuple[int, str]]
) -> float:
    """Return ``<psi|P|psi>`` for a Pauli product *P*.

    The state is renormalized once (gate evolution drifts the norm by a
    few ulps, mirroring the explicit normalization in the metrics path),
    so the global-identity observable is exactly 1.
    """
    norm = math.sqrt(math.fsum(abs(amplitude) ** 2 for amplitude in state))
    if norm == 0.0:
        return 0.0

    x_bits, y_bits, z_bits = _phase_bits(operators)
    flip_bits = x_bits | y_bits

    terms: list[float] = []
    if flip_bits == 0:
        # P is diagonal (only Z/I): P|j> = (-1)**<z,j> |j>.
        for index, amplitude in enumerate(state):
            parity = (index & z_bits).bit_count()
            weight = abs(amplitude) ** 2
            terms.append((-weight if parity & 1 else weight) / (norm * norm))
        return math.fsum(terms)

    y_count = (y_bits.bit_count() & 3)
    for index, amplitude in enumerate(state):
        flipped = index ^ flip_bits
        z_parity = (index & z_bits).bit_count()
        y_parity = (index & y_bits).bit_count()
        phase = _pauli_phase(index, z_parity, y_count, y_parity)
        value = (state[flipped].conjugate() * phase * amplitude) / (norm * norm)
        terms.append(value.real)
    return math.fsum(terms)


def density_matrix_expectation(
    rho: list[list[complex]], operators: list[tuple[int, str]]
) -> float:
    """Return ``Tr(rho P)`` for a Pauli product *P*.

    Uses ``Tr(rho P) = sum_j <j xor F|rho|j> phase(j)`` where *F* is the
    bit mask of the X/Y sites; *rho* must already be normalized to unit
    trace.
    """
    x_bits, y_bits, z_bits = _phase_bits(operators)
    flip_bits = x_bits | y_bits

    if flip_bits == 0:
        terms: list[float] = []
        for index, row in enumerate(rho):
            diagonal = row[index].real
            parity = (index & z_bits).bit_count()
            terms.append(-diagonal if parity & 1 else diagonal)
        return math.fsum(terms)

    y_count = y_bits.bit_count() & 3
    terms = []
    for index in range(len(rho)):
        z_parity = (index & z_bits).bit_count()
        y_parity = (index & y_bits).bit_count()
        phase = _pauli_phase(index, z_parity, y_count, y_parity)
        value = rho[index ^ flip_bits][index] * phase
        terms.append(value.real)
    return math.fsum(terms)

